/**
 * Generate one DSH agent preset per Solo-Code agent.
 *
 * A preset is a bundle-shipped YAML patch that inserts one
 * `@deepseek-ai/dsh-agent-preset` row. The shipped `standard` preset supplies
 * the tool composition; only the preset identity and the persona text change
 * per agent, so the generated files stay comparable with the shipped ones.
 *
 * Usage: node scripts/generate-presets.mjs [path-to-standard.patch.yml]
 */

import { mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { parseFrontmatter } from '../skills.js'

const PACKAGE = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const TEMPLATE =
  process.argv[2] ??
  resolve(PACKAGE, '../../../../../deepseek-harness-master/packages/bundle/web-app/presets/standard.patch.yml')
const AGENTS = join(PACKAGE, 'agents')
const OUT = join(PACKAGE, 'presets')
const PERSONA_CAP = 6000

function indented(text, spaces) {
  const pad = ' '.repeat(spaces)
  return text
    .split(/\r?\n/)
    .map((line) => (line.length === 0 ? '' : pad + line))
    .join('\n')
}

const template = readFileSync(TEMPLATE, 'utf-8')
const agents = readdirSync(AGENTS, { withFileTypes: true })
  .filter((entry) => entry.isFile() && entry.name.toLowerCase().endsWith('.md'))
  .map((entry) => {
    const raw = readFileSync(join(AGENTS, entry.name), 'utf-8')
    const { fields, body } = parseFrontmatter(raw)
    const stem = entry.name.slice(0, -3)
    const name = typeof fields.name === 'string' && fields.name.length > 0 ? fields.name : stem
    const description = fields.description ?? `${name} role from the Solo-Code harness`
    return { stem, name, description, body: body.trim() }
  })
  .sort((left, right) => left.stem.localeCompare(right.stem))

mkdirSync(OUT, { recursive: true })
const written = []
for (const [index, agent] of agents.entries()) {
  const role = [
    `You are the ${agent.name} agent of the Solo-Code harness. ${agent.description}`,
    'Report findings with file and line evidence; never claim a check you did not run.',
    agent.body.slice(0, PERSONA_CAP),
  ].join('\n\n')
  let patch = template
    .replace('- id: preset-standard', `- id: preset-solo-${agent.stem}`)
    .replace('        id: standard', `        id: solo-${agent.stem}`)
    .replace('        order: 1', `        order: ${20 + index}`)
    .replace(
      '              prefix: You are a coding agent powered by the {{model}} model.',
      `              prefix: |-\n${indented(role, 16)}`,
    )
  patch = patch.replace(
    '# Agent preset standard:',
    `# Agent preset solo-${agent.stem}: generated by scripts/generate-presets.mjs.`,
  )
  const file = join(OUT, `agent-${agent.stem}.patch.yml`)
  writeFileSync(file, patch, 'utf-8')
  written.push(file)
}

console.log(`generated ${written.length} presets in ${OUT}`)
